 "content": "def transform(grid):
    """Extend colored markers upward from a horizontal row of 1s.

    Color 2 endpoints are four cells above their marker; color 8 endpoints
    are three cells above. The intervening ray cells are colored 1.
    """
    out = [row[:] for row in grid]
    lengths = {2: 4, 8: 3}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color not in lengths:
                continue
            for distance in range(1, lengths[color] + 1):
                rr = r - distance
                if rr < 0:
                    break
                out[rr][c] = color if distance == lengths[color] else 1
    return out
